import { SECTION_TINT, type Tint } from './tint.ts';
import { config } from '../../site.config.ts';

const { person, contact } = config;

export const site = {
  name: person.legalName,
  firstName: person.firstName,
  lastName: person.lastName,
  role: person.role,
  url: config.site.url,
  email: contact.email,
  location: contact.location,
  booking: contact.booking.url,
  bookingLabel: contact.booking.label,
  newsletter: config.newsletter.url,
  resume: config.documents.resume,
  cv: config.documents.cv,
  description: person.description,
  // Generated by `npm run covers -- --site` (scripts/generate-blog-covers.mjs),
  // same branded card design as blog post covers, instead of a personal photo.
  ogImage: config.site.ogImage,
  portrait: config.site.portrait,
  analyticsId: config.site.analyticsId,
  googleSiteVerification: config.site.googleSiteVerification,
  legalUpdated: config.site.legalUpdated,
  blogDescription: config.site.blogDescription,
} as const;

export const github = config.github;
export const githubRepo = `${github.owner}/${github.repo}`;
export const githubUrl = `https://github.com/${githubRepo}`;

/**
 * Giscus, for blog-post comments. The widget only mounts once `repoId` and
 * `categoryId` are filled in (site.config.ts): giscus.app rejects a mount
 * without them, and a visible "giscus is not installed" error is worse than
 * no comments at all.
 */
export const giscus = { repo: githubRepo, ...config.giscus } as const;

export const nav = config.nav;

const navItem = (text: string) => {
  const item = config.nav.find((n) => n.text === text);
  return { text, href: item?.href ?? '/', tip: item?.tip };
};

export const navGroups = [
  { text: 'Work', items: ['Projects', 'Publications', 'Experience'].map(navItem) },
  {
    text: 'Background',
    items: [
      navItem('About'),
      { text: 'Education', href: '/education/', tip: 'Degrees and training' },
      navItem('Awards'),
      navItem('CV'),
    ],
  },
  {
    text: 'Writing',
    items: [
      navItem('Blog'),
      ...(site.newsletter
        ? [{ text: 'Newsletter', href: site.newsletter, tip: 'Subscribe by email', external: true }]
        : []),
    ],
  },
] as { text: string; items: { text: string; href: string; tip?: string; external?: boolean }[] }[];

/** Icon and color for each desktop nav dropdown card, keyed by item text. */
export const navMeta: Record<string, { icon: string; tint: Tint }> = {
  Projects: { icon: 'terminal', tint: SECTION_TINT.Projects! },
  Publications: { icon: 'book', tint: SECTION_TINT.Publications! },
  Experience: { icon: 'briefcase', tint: SECTION_TINT.Experience! },
  About: { icon: 'users', tint: SECTION_TINT.About! },
  Education: { icon: 'graduationCap', tint: SECTION_TINT.Education! },
  Awards: { icon: 'trophy', tint: SECTION_TINT.Awards! },
  CV: { icon: 'file', tint: SECTION_TINT.CV! },
  Blog: { icon: 'pencil', tint: SECTION_TINT.Blog! },
  Newsletter: { icon: 'mail', tint: SECTION_TINT.Newsletter! },
};

export const socials = config.socials;

export const skills = config.skills as [string, string][];
